import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_zz9999():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags_normalized():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_absolute_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# B§1 prose rules
def test_parse_ref_a1_is_origin():
    assert parse_ref("A1") == Ref(0, 0)


def test_parse_ref_z_and_aa_columns():
    assert parse_ref("Z1") == Ref(25, 0)
    assert parse_ref("AA1") == Ref(26, 0)


def test_parse_ref_max_row_and_col():
    assert parse_ref("ZZ9999") == Ref(701, 9998)


def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_ref_lowercase_accepted():
    assert parse_ref("b2") == Ref(1, 1)


def test_parse_ref_partial_dollar_rejected():
    with pytest.raises(ValueError):
        parse_ref("$A1$")


def test_parse_ref_empty_rejected():
    with pytest.raises(ValueError):
        parse_ref("")


def test_parse_ref_trailing_text_rejected():
    with pytest.raises(ValueError):
        parse_ref("A1B")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# parse_range
def test_range_single_cell_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_range_normalizes_reversed_corners():
    assert parse_range("C3:A1") == (Ref(0, 0), Ref(2, 2))


def test_range_tie_takes_first_corner_flags():
    assert parse_range("$A$1:A1") == (Ref(0, 0, True, True), Ref(0, 0))


def test_range_bad_corner_rejected():
    with pytest.raises(ValueError):
        parse_range("A0:B2")


def test_range_three_parts_rejected():
    with pytest.raises(ValueError):
        parse_range("A1:B2:C3")


# to_a1
def test_to_a1_plain():
    assert to_a1(Ref(0, 0)) == "A1"


def test_to_a1_both_absolute():
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"


def test_to_a1_row_absolute_only():
    assert to_a1(Ref(1, 11, False, True)) == "B$12"


def test_to_a1_row_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))


def test_to_a1_negative_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(-1, 0))


def test_round_trip():
    for text in ["A1", "B12", "$AA$7", "ZZ9999", "$Z3"]:
        assert to_a1(parse_ref(text)) == text.upper()

