def parse_ref(s: str) -> Ref:
    """Contract: see plan task T8."""
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid cell reference: {s!r}")
    abs_col_flag, letters, abs_row_flag, digits = m.groups()
    col = 0
    for ch in letters.upper():
        col = col * 26 + (ord(ch) - ord("A") + 1)
    return Ref(col - 1, int(digits) - 1, bool(abs_col_flag), bool(abs_row_flag))


def parse_range(s: str) -> tuple[Ref, Ref]:
    """Contract: see plan task T8."""
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    a = parse_ref(parts[0])
    b = parse_ref(parts[1])
    # Each axis: the corner supplying min/max supplies its $ flag (tie: first corner).
    if a.col <= b.col:
        lo_col, lo_abs_col, hi_col, hi_abs_col = a.col, a.abs_col, b.col, b.abs_col
    else:
        lo_col, lo_abs_col, hi_col, hi_abs_col = b.col, b.abs_col, a.col, a.abs_col
    if a.row <= b.row:
        lo_row, lo_abs_row, hi_row, hi_abs_row = a.row, a.abs_row, b.row, b.abs_row
    else:
        lo_row, lo_abs_row, hi_row, hi_abs_row = b.row, b.abs_row, a.row, a.abs_row
    return (
        Ref(lo_col, lo_row, lo_abs_col, lo_abs_row),
        Ref(hi_col, hi_row, hi_abs_col, hi_abs_row),
    )


def to_a1(ref: Ref) -> str:
    """Contract: see plan task T8."""
    if not (0 <= ref.col <= 701 and 0 <= ref.row <= 9998):
        raise ValueError(f"cell reference out of range: {ref!r}")
    n = ref.col + 1
    letters = ""
    while n > 0:
        n, r = divmod(n - 1, 26)
        letters = chr(ord("A") + r) + letters
    return (
        ("$" if ref.abs_col else "")
        + letters
        + ("$" if ref.abs_row else "")
        + str(ref.row + 1)
    )

